INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48511, 'Exodus 1:19', 'Exodus', 1, 19, 'هغوی په ځواب کې وویل: «عبرانۍ ښځې د مصریو ښځو په پرتله زر ماشوم زېږوي او زمونږ د رسېدلو څخه مخکې د هغوی ماشوم پیدا کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_19.mp3', '', 1761754199, 1761754199),
(48512, 'Exodus 1:22', 'Exodus', 1, 22, 'په پای کې فرعون ټول قوم ته امر وکړ: «څنګه چې عبرانی هلک پیدا کیږي، تاسو به هغه د نیل په سیند کې غورځوئ. خو ټولې نجونې ژوندۍ پرېږدئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus1_verse_22.mp3', '', 1761754199, 1761754199),
(48513, 'Isaiah 49:1', 'Isaiah', 49, 1, 'ای د لېرې هېوادونو خلکو، ماته غوږ ونیسئ! ای هغو خلکو چې اوسېږئ لېرې وکړئ پام زما خبرو ته! زه څښتن خدای وم غوره کړی زېږېدو نه مخکې او زه یې وټاکلم د خپل خدمتګار په توګه د مور له ګېډۍ څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_1.mp3', '', 1761754199, 1761754199),
(48514, 'Isaiah 49:2', 'Isaiah', 49, 2, 'هغه تېره کړه زما ژبه لکه د تورې په شان او د خپل لاس د سیوري لاندې یې وکړه ساتنه زما زه یې تېره کړم لکه د غشي په شان او پټ یې وساتلم د خپلو غشو په کڅوړه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_2.mp3', '', 1761754199, 1761754199),
(48515, 'Isaiah 49:3', 'Isaiah', 49, 3, 'هغه وویل ماته: «ته اسراییل یې خدمتګار زما او ته به سبب شې د دې چې زه وښایمه خپله لویي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_3.mp3', '', 1761754199, 1761754199),
(48516, 'Isaiah 49:4', 'Isaiah', 49, 4, 'خو ما وویل له ځانه سره: «ما وویست زیار خو ؤ بې ګټې هغه ولګاوه ما خپل ټول قوت بېځایه خو بیاهم لرم باور په څښتن چې دفاع وکړي زما زه یم ډاډه چې هغه به راته اجر راکړي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_4.mp3', '', 1761754199, 1761754199),
(48517, 'Isaiah 49:5', 'Isaiah', 49, 5, 'څښتن زه جوړ کړمه د مور په خېټه کې چې خدمتګار شم د هغه ترڅو راولم زه د هغه خواته بېرته قوم د یعقوب او سره راغونډ کړم د اسراییلو خواره واره خلک لرم عزت زه د څښتن نظر کې او ماته یې قوت راکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_5.mp3', '', 1761754199, 1761754199),
(48518, 'Isaiah 49:6', 'Isaiah', 49, 6, 'ماته وویل هغه: «دا کافي نه ده، ای خدمتګاره زما چې ته یوازې خدمتګار اوسې زما ترڅو قبیلې کړې ځای په ځای د یعقوب او بېرته راولې د اسراییلو ژوندي پاتې خلک بلکې تا نه به جوړه کړم رڼا د قومو دپاره ترڅو ورسي خلاصون زما ټولې نړۍ ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_6.mp3', '', 1761754199, 1761754199),
(48519, 'Isaiah 49:7', 'Isaiah', 49, 7, 'چې کتل کیږي چاته په سپکه سترګه د هغه چا څخه چې قومونه کوي کرکه هغه څوک چې غلام شوی د حکمرانانو له خوا ژغورونکی او سپېڅلی خدای د اسراییلو هغه ته داسې وایي: «پاچاهان چې کله وګوري تا تاته به پاڅیږي د درناوي په خاطر شاهزادګان چې کله وګوري تا تاته ټیټیږي به د درناوي په خاطر ځکه څښتن دی وفادار او غوره کړی یې ته سپېڅلي خدای د اسراییلو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_7.mp3', '', 1761754199, 1761754199),
(48520, 'Isaiah 49:8', 'Isaiah', 49, 8, 'څښتن داسې وایي: «په سم وخت کې چې د ژغورنې ورځ ده زه به واورمه ستا چیغې د کومک دپاره زه به وکړمه ساتنه او ملاتړ ستا او لوظ به وکړم زه د خلکو سره ستا په وسیله ته یوځل بیا به کړې اباده هغه ځمکه او هغه به ووېشې چې اوس پرته ده ورانه او ویجاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_8.mp3', '', 1761754199, 1761754199),
(48521, 'Isaiah 49:9', 'Isaiah', 49, 9, 'بندیانو ته به ووایې ته چې راوځئ او ازاد شئ! او چې په تیارو کې دي څوک هغوی ته وبه وایې تاسو راووځئ رڼا ته! هغوی به وڅري لکه پسونو په شان د لارو څنګ کې او کړي پیدا به خواړه په ټولو وچو او شاړو غونډیو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_9.mp3', '', 1761754199, 1761754199),
(48522, 'Isaiah 49:10', 'Isaiah', 49, 10, 'هغوی به نه شي هېڅ وخت وږي تږي، نه به لمر او نه سوځوونکې ګرمي هغوی ته ورسوي زیان ځکه هغوی ته کیږي لارښوونه به د هغه چا له خوا چې خواخوږی لري هغوی سره او هغه به بیایي هغوی د اوبو چینو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_10.mp3', '', 1761754199, 1761754199),
(48523, 'Isaiah 49:11', 'Isaiah', 49, 11, 'د غرونو منځ کې به زه جوړه کړمه لاره او خپلو خلکو ته تیارې به کړم لویې لارې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_11.mp3', '', 1761754199, 1761754199),
(48524, 'Isaiah 49:12', 'Isaiah', 49, 12, 'ګورئ، زما خلک به راشي د لېرې ځایه څخه ځینې به راشي له شماله او ځینې له لوېدیځ څخه او ځینې جنوب کې له اسوان څخه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_12.mp3', '', 1761754199, 1761754199),
(48525, 'Isaiah 49:13', 'Isaiah', 49, 13, 'ای اسمانونو ووایئ د خوشحالۍ سندرې! ای ځمکې خوشحاله اوسه! او ای غرونو ووایئ د خوشحالۍ سندرې ځکه ورکړې تسلي ده خپل قوم ته څښتن او رحم به وکړي هغه په خپلو کړېدلو خلکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_13.mp3', '', 1761754199, 1761754199),
(48526, 'Isaiah 49:14', 'Isaiah', 49, 14, 'خو صهیون وویل: «زه یم پریښی څښتن! زه یم هېر کړی څښتن!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_14.mp3', '', 1761754199, 1761754199),
(48527, 'Isaiah 49:15', 'Isaiah', 49, 15, 'نو په ځواب کې څښتن وویل: «ایا یوه مور شي هېرولی خپل تی رودونکی ماشوم؟ ایا کولای شي چې ونه کړي مینه هغه ماشوم سره چې زېږولی یې وي؟ که بیاهم یوه مور هېر کړي خپل ماشوم خو زه به هېڅکله هېر نه کړمه تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_15.mp3', '', 1761754199, 1761754199),
(48528, 'Isaiah 49:16', 'Isaiah', 49, 16, 'ای اورشلیمه، زه دې هېڅکله هېرولی نه شم! ما ستا تصویر ایستلی په ورغویو د خپلو لاسونو تل په فکر کې یم ستا د دېوالونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_16.mp3', '', 1761754199, 1761754199),
(48529, 'Isaiah 49:17', 'Isaiah', 49, 17, 'څوک چې تا بیا جوړوي، هغوی به زر راشي خو هغو خلکو چې وران کړی یې ته ستا نه به ووځي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_17.mp3', '', 1761754199, 1761754199),
(48530, 'Isaiah 49:18', 'Isaiah', 49, 18, 'وګوره شاوخوا ته او نظر وکړه چې څه کیږي! ستا ټول خلک راغونډیږي او دي راروان ستا خواته زه قسم خورم په خپل ژوند باندې ته به ویاړ وکړې خپلو خلکو باندې داسې ویاړ چې کوي یې ناوې خپلو ګاڼو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_18.mp3', '', 1761754199, 1761754199),
(48531, 'Isaiah 49:19', 'Isaiah', 49, 19, 'په رښتیا ستا وطن ؤ وران او ویجاړ شوی خو هغه به ډک شي اوس د خلکو څخه او ډېر وړوکی او وي به تنګ د هغو خلکو اوسېدو دپاره هغه خلک چې بدل کړی یې ته په کنډوالو باندې ستا نه به لېرې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_19.mp3', '', 1761754199, 1761754199),
(48532, 'Isaiah 49:20', 'Isaiah', 49, 20, 'ستا کوم خلک چې زېږېدلي دي جلاوطنۍ کې یو وخت به تاته هغوی ووایي: ‹دا ځای وړوکی او ډېر تنګ دی زمونږ دپاره مونږ ته راکړه نوره پراخه ځمکه د اوسېدو دپاره›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_20.mp3', '', 1761754199, 1761754199),
(48533, 'Isaiah 49:21', 'Isaiah', 49, 21, 'بیا به پوښتنه وکړې ته د خپل ځان څخه: ‹چا راوړي دومره اولادونه دې نړۍ ته ماته؟ ما خو له لاسه دي ورکړي اولادونه خپل او نه مې کیږي اولادونه نور جلاوطنه شول او وشړل شول زما پاتې ژوندي خلک بیا چا وروزل دا ماشومان؟ زه خو یوازې پاتې شوی ومه دا ماشومان له کومه ځایه راغلل؟›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_21.mp3', '', 1761754199, 1761754199),
(48534, 'Isaiah 49:22', 'Isaiah', 49, 22, 'څښتن تعالی داسې وایي: «ګوره، زه به وکړم اشاره پردي قومونو ته او زه به هغوی ته خپل بیرغ پورته کړم هغوی به راوړي ستا زامن په غېږ کې او ستا لوڼې خپلو اوږو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_22.mp3', '', 1761754199, 1761754199),
(48535, 'Isaiah 49:23', 'Isaiah', 49, 23, 'داسې به وي پاچاهان ستا دپاره لکه پلرونو په شان او ملکې لکه د میندو په شان هغوی به ټیټ شي ستا په وړاندې او څټي به خاورې ستا د پښو نو بیا به پوه شې ته چې زه څښتن یم څوک چې په تمه وي زما کومک ته ناامیده کیږي به نه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_23.mp3', '', 1761754199, 1761754199),
(48536, 'Isaiah 49:24', 'Isaiah', 49, 24, 'ایا کولای شي څوک چې غنیمت د جګړې واخلي له جنګیالي نه؟ او یا څوک شي خلاصولی بندیان د کوم ظالم حکمران له لاسه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_24.mp3', '', 1761754199, 1761754199),
(48537, 'Isaiah 49:25', 'Isaiah', 49, 25, 'خو څښتن داسې وایي: «حتی خلاص به اسیران شي د جنګیالي له لاسه او د ظالم حکمران څخه به ونیول شي د غنیمت مالونه هرڅوک چې تا سره جګړه کوي د هغوی سره به وجنګېږم زه او اولادونه به ستا وژغورمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_25.mp3', '', 1761754199, 1761754199),
(48538, 'Isaiah 49:26', 'Isaiah', 49, 26, 'په دښمنانو به دې وخورم د یو او بل د بدن غوښې د یو او بل د وینو په څښلو به داسې نشه شي هغوی د شرابو د نشې په شان بیا به ټول انسانان پوه شي چې زه څښتن یمه ژغورونکی ستا او د یعقوب زورور خدای یمه چې ازادوم تا»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah49_verse_26.mp3', '', 1761754199, 1761754199),
(48539, 'Genesis 29:1', 'Genesis', 29, 1, 'نو یعقوب خپل سفر ته دوام ورکړ او د مشرق د خلکو خاورې ته راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_1.mp3', '', 1761754199, 1761754199),
(48540, 'Genesis 29:2', 'Genesis', 29, 2, 'هغه په صحرا کې یوه څاه ولیدله چې د پسونو درې رمې یې په څنګ کې پنډې وې. له دې څاه څخه به رمو اوبه څښلې او د څاه خولې ته یوه لویه تیږه ایښې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_2.mp3', '', 1761754199, 1761754199),
(48541, 'Genesis 29:3', 'Genesis', 29, 3, 'کله چې به ټولې رمې هلته راټولې شوې، نو شپنو به دغه تیږه د څاه د خولې څخه لېرې کوله او رمو ته به یې اوبه ورکولې. بیا به یې تیږه بېرته د څاه خولې ته ایښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_3.mp3', '', 1761754199, 1761754199),
(48542, 'Genesis 29:4', 'Genesis', 29, 4, 'یعقوب د شپنو څخه پوښتنه وکړه: «ای زما ورونو، تاسو د کوم ځای یئ؟» هغوی ځواب ورکړ: «مونږ د حران یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_4.mp3', '', 1761754199, 1761754199),
(48543, 'Genesis 29:5', 'Genesis', 29, 5, 'هغه پوښتنه وکړه: «تاسو د ناحور لمسی لابان پېژنئ؟» هغوی ځواب ورکړ: «هو، مونږ هغه پېژنو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_5.mp3', '', 1761754199, 1761754199),
(48544, 'Genesis 29:6', 'Genesis', 29, 6, 'هغه پوښتنه وکړه: «هغه ښه دی؟» هغوی ځواب ورکړ: «هغه ښه دی. وګوره، دا د هغه لور راحیل ده چې د خپلې رمې سره راروانه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_6.mp3', '', 1761754199, 1761754199),
(48545, 'Genesis 29:7', 'Genesis', 29, 7, 'یعقوب وویل: «تر‌اوسه پورې لا لمر جګ ولاړ دی او د رمو د راټولېدلو وخت نه دی. پسونو ته اوبه ورکړئ او هغه بېرته څړځای ته بوځئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_7.mp3', '', 1761754199, 1761754199),
(48546, 'Genesis 29:8', 'Genesis', 29, 8, 'هغوی وویل: «دا کار مونږ نه شو کولای. کله چې ټولې رمې راټولې شي او د څاه د خولې څخه تیږه لېرې کړای شي، بیا به پسونو ته اوبه ورکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_8.mp3', '', 1761754199, 1761754199),
(48547, 'Genesis 29:9', 'Genesis', 29, 9, 'یعقوب لا د هغوی سره خبرې کولې چې راحیل د رمې سره راغله، ځکه چې هغه شپونکۍ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_9.mp3', '', 1761754199, 1761754199),
(48548, 'Genesis 29:10', 'Genesis', 29, 10, 'کله چې یعقوب راحیل ولیدله چې د هغه د ماما لابان رمه ورسره وه، هغه څاه ته ورغی او تیږه یې د څاه د خولې څخه لېرې کړه او د لابان پسونو ته یې اوبه ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_10.mp3', '', 1761754199, 1761754199),
(48549, 'Genesis 29:11', 'Genesis', 29, 11, 'بیا یعقوب راحیل ښکل کړه او په لوړ اواز سره یې وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_11.mp3', '', 1761754199, 1761754199),
(48550, 'Genesis 29:12', 'Genesis', 29, 12, 'یعقوب راحیل ته وویل: «زه ستا د پلار د خپلوانو څخه یم او د ربکا زوی یم.» هغه په منډه لاړه او خپل پلار یې خبر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_12.mp3', '', 1761754199, 1761754199),
(48551, 'Genesis 29:13', 'Genesis', 29, 13, 'څنګه چې لابان د خپل خوریي یعقوب خبر واورېد، نو په منډه د هغه لیدلو ته ورغی. هغه یې په غېږ کې ونیوه، ښکل یې کړ او خپل کور ته یې راوست. بیا هرڅه چې پېښ شوي وو، یعقوب لابان ته بیان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_13.mp3', '', 1761754199, 1761754199),
(48552, 'Genesis 29:14', 'Genesis', 29, 14, 'لابان هغه ته وویل: «په رښتیا سره ته زما خپله وینه او خپل هډوکی یې.» یعقوب پوره یوه میاشت د هغه سره پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_14.mp3', '', 1761754199, 1761754199),
(48553, 'Genesis 29:15', 'Genesis', 29, 15, 'لابان یعقوب ته وویل: «ایا په دې خاطر چې ته زما خپل یې، نو ماته به وړیا خدمت کوې؟ ووایه چې ته څومره مزدوري غواړې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_15.mp3', '', 1761754199, 1761754199),
(48554, 'Genesis 29:16', 'Genesis', 29, 16, 'لابان دوه لورګانې درلودلې، د مشرې نوم لیه او د کشرې نوم راحیل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_16.mp3', '', 1761754199, 1761754199),
(48555, 'Genesis 29:17', 'Genesis', 29, 17, 'د لیه سترګې ښکلې وې، خو راحیل ښایسته وه او ښکلی اندام یې درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_17.mp3', '', 1761754199, 1761754199),
(48556, 'Genesis 29:18', 'Genesis', 29, 18, 'یعقوب په راحیل باندې مین شوی ؤ او ویې ویل: «که چېرې خپله کشره لور ماته راکړې، نو زه به اووه کاله ستا خدمت وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_18.mp3', '', 1761754199, 1761754199),
