(48558, 'Genesis 29:20', 'Genesis', 29, 20, 'نو یعقوب د راحیل دپاره اووه کاله خدمت وکړ، خو دا کلونه هغه ته لکه د ډېرو لږو ورځو په شان ښکاره شول، ځکه چې هغه د راحیل سره ډېره مینه درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_20.mp3', '', 1761754199, 1761754199),
(48559, 'Genesis 29:21', 'Genesis', 29, 21, 'نو یعقوب لابان ته وویل: «هغه موده پوره شوې ده، نو اجازه راکړه چې ستا د لور سره واده وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_21.mp3', '', 1761754199, 1761754199),
(48560, 'Genesis 29:22', 'Genesis', 29, 22, 'نو لابان د هغه ځای ټول خلک راټول کړل او مېلمستیا یې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_22.mp3', '', 1761754199, 1761754199),
(48561, 'Genesis 29:23', 'Genesis', 29, 23, 'خو کله چې شپه شوه، هغه د راحیل په ځای لیه یعقوب ته وروستله او یعقوب د هغې سره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_23.mp3', '', 1761754199, 1761754199),
(48562, 'Genesis 29:24', 'Genesis', 29, 24, 'لابان خپله وینځه زلفه خپلې لور لیه ته د نوکرې په توګه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_24.mp3', '', 1761754199, 1761754199),
(48563, 'Genesis 29:25', 'Genesis', 29, 25, 'کله چې سهار شو، یعقوب ته معلومه شوه چې هغه لیه وه. هغه لابان ته ورغی او ورته ویې ویل: «زما سره دې ولې داسې وکړل؟ ما د دې دپاره کار کاوه چې راحیل ماته راکړې، زه دې ولې وغولولم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_25.mp3', '', 1761754199, 1761754199),
(48564, 'Genesis 29:26', 'Genesis', 29, 26, 'لابان ځواب ورکړ: «دلته زمونږ په ځای کې داسې رواج نه دی چې کشره لور دې د مشرې څخه مخکې واده کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_26.mp3', '', 1761754199, 1761754199),
(48565, 'Genesis 29:27', 'Genesis', 29, 27, 'صبر وکړه چې د لیه د واده اوومه ورځ پوره شي بیا به راحیل هم درکړم، خو ته به اووه کاله نور هم زما خدمت کوې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_27.mp3', '', 1761754199, 1761754199),
