(48567, 'Genesis 29:29', 'Genesis', 29, 29, 'لابان خپله وینځه بلهه خپلې لور راحیل ته د نوکرې په توګه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_29.mp3', '', 1761754199, 1761754199),
(48568, 'Genesis 29:30', 'Genesis', 29, 30, 'یعقوب د راحیل سره هم یوځای شو. په هغه باندې د لیه څخه راحیل ډېره ګرانه وه. هغه لابان ته اووه کاله نور خدمت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_30.mp3', '', 1761754199, 1761754199),
(48569, 'Genesis 29:31', 'Genesis', 29, 31, 'کله چې څښتن ولیدل چې یعقوب د لیه سره ډېره مینه نه کوي، خدای هغې ته اولادونه ورکړل، خو راحیل شنډه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_31.mp3', '', 1761754199, 1761754199),
(48570, 'Genesis 29:32', 'Genesis', 29, 32, 'لیه امیدواره شوه او زوی یې وزېږاوه او په هغه باندې یې روبین نوم کېښود، ځکه هغې وویل: «څښتن زما سختي لیدلې ده. اوس به مې مېړه راسره مینه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_32.mp3', '', 1761754199, 1761754199),
(48571, 'Genesis 29:33', 'Genesis', 29, 33, 'هغه بیا امیدواره شوه، زوی یې وزېږاوه او ویې ویل: «دا ځکه چې څښتن پوهیږي چې یعقوب زما سره مینه نه کوي، نو دا یې هم راکړ.» نو په هغه باندې یې شمعون نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_33.mp3', '', 1761754199, 1761754199),
(48572, 'Genesis 29:34', 'Genesis', 29, 34, 'هغه بیا امیدواره شوه او زوی یې وزېږاوه، ویې ویل: «اوس به د خپل مېړه زړه ته ورنژدې شم، ځکه چې درې زامن مې ورته وزېږول.» نو په دې خاطر یې په هغه باندې لاوي نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_34.mp3', '', 1761754199, 1761754199),
(48573, 'Genesis 29:35', 'Genesis', 29, 35, 'هغه بیا امیدواره شوه او کله چې د هغې زوی پیدا شو، هغې وویل: «دا ځل به زه د څښتن ستاینه وکړم.» نو هغې په هغه باندې یهودا نوم کېښود. وروسته له هغې څخه لیه د اولاد د زېږولو څخه ولوېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis29_verse_35.mp3', '', 1761754199, 1761754199),
(48574, 'Habakkuk 3:1', 'Habakkuk', 3, 1, 'دا د حبقوق پیغمبر دعا ده چې د سندرې په شکل ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk3_verse_1.mp3', '', 1761754199, 1761754199),
(48575, 'Habakkuk 3:2', 'Habakkuk', 3, 2, 'ای څښتنه، تا چې کړي کوم کارونه ترې خبر یمه زه او په ما راغلې وېره تا چې کول کوم کارونه پخوا اوس یې بیا وکړه زمانه کې زمونږ کله چې ته په قهر هم یې نو اوسه رحیم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk3_verse_2.mp3', '', 1761754199, 1761754199),
(48576, 'Habakkuk 3:3', 'Habakkuk', 3, 3, 'خدای راروان دی یوځل بیا له ادومه څخه سپېڅلی خدای دی راروان د فاران له غره نه دي اسمانونه پټ د هغه په شان او شوکت او ثنا او صفت نه یې ده ډکه ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk3_verse_3.mp3', '', 1761754199, 1761754199),
(48577, 'Habakkuk 3:4', 'Habakkuk', 3, 4, 'هغه راځي د برېښنا له رڼا سره رڼا ځلیږي د لاسونو نه یې چې په کې پټ دی قدرت د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk3_verse_4.mp3', '', 1761754199, 1761754199),
